<script setup lang="ts">
import { nextTick, ref } from 'vue';import { useRoute } from 'vue-router';import { ChatDotRound,Delete,Document,Promotion,RefreshRight } from '@element-plus/icons-vue';import { useSessionStore,type ChatMessage } from '@ygh/web-shared'
const session=useSessionStore();const route=useRoute();const input=ref(String(route.query.q||''));const sending=ref(false);const scroll=ref<HTMLElement>();const messages=ref<ChatMessage[]>([{id:'welcome',role:'ASSISTANT',content:'您好，我是跨境智汇 AI 客服。我可以依据已发布知识和授权商品信息，回答跨境政策、通关流程、商品溯源以及您的订单问题。',createdAt:new Date().toISOString()}])
const conversations=ref([{id:'1',title:'跨境进口限值咨询',time:'今天 10:24'},{id:'2',title:'三文鱼商品溯源',time:'昨天 16:08'},{id:'3',title:'订单支付状态',time:'07-11'}])
async function send(){const text=input.value.trim();if(!text||sending.value)return;messages.value.push({id:crypto.randomUUID(),role:'USER',content:text,createdAt:new Date().toISOString()});input.value='';sending.value=true;await nextTick();scroll.value?.scrollTo({top:scroll.value.scrollHeight});setTimeout(()=>{messages.value.push({id:crypto.randomUUID(),role:'ASSISTANT',content:text.includes('限值')?'跨境电商零售进口商品的限值需要结合当前有效政策与个人年度累计交易额判断。系统正式联调后会从知识库返回具体限值、适用范围和政策版本；当前原型不虚构实时法规数字。':'我已理解您的问题。正式联调时，我会先检索已发布知识，再结合权限允许的商品、溯源或本人订单只读信息生成回答。',createdAt:new Date().toISOString(),citations:[{documentId:'k-101',chunkId:'c-12',title:'跨境电商零售进口商品清单与限值说明',excerpt:'个人交易限值与适用范围应以当前有效政策版本为准。'}]});sending.value=false;nextTick(()=>scroll.value?.scrollTo({top:scroll.value.scrollHeight,behavior:'smooth'}))},650)}
;</script>
<template><div class="ai-shell"><aside><div class="ai-brand"><span>AI</span><div><b>跨境智汇客服</b><small>可信检索增强问答</small></div></div><el-button type="primary" plain class="new-chat" :icon="ChatDotRound" @click="messages=messages.slice(0,1)">新建会话</el-button><p>最近会话</p><button v-for="c in conversations" :key="c.id"><ChatDotRound/><span><b>{{c.title}}</b><small>{{c.time}}</small></span></button><div class="ai-boundary"><b>能力边界</b><span>✓ 已发布知识</span><span>✓ 商品与溯源</span><span>✓ 本人订单只读</span><span>× 不修改交易数据</span></div></aside><main><header><div><span class="status-dot"/><b>专业客服在线</b><small>回答由知识库与业务工具共同支撑</small></div><el-button text :icon="Delete" @click="messages=messages.slice(0,1)">清空</el-button></header><div ref="scroll" class="messages"><div v-if="!session.authenticated" class="login-notice"><b>登录后可查询本人订单与保存历史会话</b><el-button size="small" type="primary" @click="$router.push('/login')">去登录</el-button></div><article v-for="m in messages" :key="m.id" :class="m.role.toLowerCase()"><div class="avatar">{{m.role==='USER'?'我':'智'}}</div><div class="message-body"><div class="bubble">{{m.content}}</div><div v-if="m.citations?.length" class="citations"><b><Document/>回答引用 {{m.citations.length}} 条</b><RouterLink v-for="c in m.citations" :key="c.chunkId" :to="`/knowledge/${c.documentId}`"><span>{{c.title}}</span><small>{{c.excerpt}}</small></RouterLink></div></div></article><article v-if="sending" class="assistant"><div class="avatar">智</div><div class="bubble typing"><i/><i/><i/></div></article></div><footer><div class="suggestions"><button v-for="q in ['进口零食需要哪些通关材料？','如何查看商品溯源？','查询我的待支付订单']" :key="q" @click="input=q">{{q}}</button></div><div class="composer"><el-input v-model="input" type="textarea" :autosize="{minRows:2,maxRows:5}" maxlength="1000" show-word-limit placeholder="请输入跨境政策、商品溯源或订单问题……" @keydown.ctrl.enter.prevent="send"/><el-button type="primary" :icon="Promotion" :loading="sending" @click="send">发送</el-button></div><small>AI 可能出错，请核对引用来源。Ctrl + Enter 发送。</small></footer></main></div></template>
<style scoped>.ai-shell{height:calc(100vh - 102px);min-height:650px;display:grid;grid-template-columns:270px 1fr;background:#edf1ec}.ai-shell>aside{display:flex;flex-direction:column;padding:22px;background:#0b3431;color:white}.ai-brand{display:flex;align-items:center;gap:11px}.ai-brand>span{display:grid;place-items:center;width:40px;height:40px;border:1px solid #d7bc75;color:#d7bc75;font:700 14px serif}.ai-brand b,.ai-brand small{display:block}.ai-brand small{margin-top:3px;color:#8eaaa3;font-size:10px}.new-chat{width:100%;margin:24px 0}.ai-shell aside>p{color:#77928c;font-size:11px;letter-spacing:.14em}.ai-shell aside>button{display:flex;gap:10px;padding:11px 8px;border:0;border-radius:7px;background:transparent;color:#bed0cb;text-align:left;cursor:pointer}.ai-shell aside>button:hover{background:rgba(255,255,255,.07)}.ai-shell aside>button svg{width:15px}.ai-shell aside>button b,.ai-shell aside>button small{display:block}.ai-shell aside>button b{font-size:12px}.ai-shell aside>button small{margin-top:3px;color:#708d86;font-size:10px}.ai-boundary{display:flex;flex-direction:column;gap:8px;margin-top:auto;padding:16px;background:rgba(255,255,255,.05);font-size:11px}.ai-boundary b{color:#d7bc75;margin-bottom:3px}.ai-shell>main{min-width:0;display:grid;grid-template-rows:64px 1fr auto;background:#faf9f5}.ai-shell main>header{display:flex;align-items:center;justify-content:space-between;padding:0 24px;background:#fff;border-bottom:1px solid var(--line)}.ai-shell main>header>div{display:flex;align-items:center;gap:10px}.ai-shell main>header small{color:var(--muted)}.messages{overflow:auto;padding:25px max(24px,calc((100% - 850px)/2))}.login-notice{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;padding:12px 15px;background:#fff3d6;border:1px solid #e5c980;color:#765d23;font-size:12px}.messages article{display:flex;align-items:flex-start;gap:10px;margin:20px 0}.messages article.user{flex-direction:row-reverse}.avatar{flex:0 0 34px;height:34px;display:grid;place-items:center;background:var(--jade);color:#fff;border-radius:50%;font:700 13px serif}.user .avatar{background:var(--cinnabar)}.message-body{max-width:min(78%,700px)}.bubble{padding:13px 16px;background:#fff;border:1px solid var(--line);border-radius:2px 13px 13px 13px;line-height:1.8;font-size:14px}.user .bubble{background:var(--jade);border:0;border-radius:13px 2px 13px 13px;color:white}.citations{margin-top:7px;padding:12px;background:#edf4f0;border-left:3px solid var(--jade)}.citations>b{display:flex;align-items:center;gap:5px;color:var(--jade);font-size:11px}.citations svg{width:13px}.citations a{display:block;margin-top:8px}.citations a span,.citations a small{display:block}.citations a span{font-size:12px;font-weight:600}.citations a small{margin-top:3px;color:var(--muted);font-size:10px}.typing{display:flex;gap:4px}.typing i{width:6px;height:6px;border-radius:50%;background:#87a39c;animation:pulse 1s infinite}.typing i:nth-child(2){animation-delay:.15s}.typing i:nth-child(3){animation-delay:.3s}@keyframes pulse{50%{opacity:.25;transform:translateY(-3px)}}.ai-shell main>footer{padding:13px max(24px,calc((100% - 850px)/2)) 16px;background:#fff;border-top:1px solid var(--line)}.suggestions{display:flex;gap:7px;margin-bottom:8px;overflow:auto}.suggestions button{padding:6px 10px;border:1px solid var(--line);border-radius:999px;background:#faf9f5;color:var(--muted);font-size:10px;white-space:nowrap;cursor:pointer}.composer{display:flex;align-items:end;gap:9px}.composer .el-button{height:54px}.ai-shell main>footer>small{display:block;margin-top:6px;color:#9aa49f;font-size:9px;text-align:center}@media(max-width:750px){.ai-shell{grid-template-columns:1fr}.ai-shell>aside{display:none}.message-body{max-width:88%}}</style>
